// Normalizes a price to integer cents. Callers rely on rounding half up.
export function toCents(input: Price): number {
  // v1 payloads send a string like "12.50"; drop once v1 clients are gone
  if (typeof input === "string") {
    return Math.round(parseFloat(input) * 100);
  }
  return Math.round(input.amount * 100);
}
